INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch06$PT143-S3-Q9$batch06$, 143, 3, 9, $batch06$Parallel$batch06$, $batch06$We know that if life ever existed on the Moon, there would be signs of life there. But numerous excursions to the Moon have failed to provide us with any sign of life. So there has never been life on the Moon.$batch06$, $batch06$The pattern of reasoning in the argument above is most similar to that in which one of the following?$batch06$, $batch06$E$batch06$, true, $batch06$Batch 06; question text from local bank.$batch06$ FROM lr_sections s WHERE s.preptest=143 AND s.section=3 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch06$PT143-S3-Q9$batch06$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch06$A$batch06$, $batch06$We know that the spy is a traitor. We do not know that the general is a traitor. So the general is not a spy.$batch06$, $batch06$Bad Premise Match$batch06$, false FROM lr_questions q WHERE q.qid=$batch06$PT143-S3-Q9$batch06$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch06$A$batch06$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch06$B$batch06$, $batch06$If we have any mayonnaise, it would be in the refrigerator. But the refrigerator is almost empty. So it is unlikely that we have mayonnaise.$batch06$, $batch06$Bad Conclusion Match$batch06$, false FROM lr_questions q WHERE q.qid=$batch06$PT143-S3-Q9$batch06$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch06$B$batch06$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch06$C$batch06$, $batch06$Hendricks will win the election only if voters are concerned primarily with fighting crime. Hendricks is in favor of tougher criminal penalties. So voters will probably go with Hendricks.$batch06$, $batch06$Bad Premise Match$batch06$, false FROM lr_questions q WHERE q.qid=$batch06$PT143-S3-Q9$batch06$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch06$C$batch06$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch06$D$batch06$, $batch06$If rodents are responsible for the lost grain from last year’s harvest, we would find signs of rodents in the warehouses. And we have found signs of rodents there. So rodents are responsible for the lost grain.$batch06$, $batch06$Bad Premise Match$batch06$, false FROM lr_questions q WHERE q.qid=$batch06$PT143-S3-Q9$batch06$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch06$D$batch06$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch06$E$batch06$, $batch06$If their army is planning an attack, there would either be troop movements along the border or a transfer of weapons. But intelligence reports show no indication of either. So their army is not planning an attack.$batch06$, $batch06$Correct$batch06$, true FROM lr_questions q WHERE q.qid=$batch06$PT143-S3-Q9$batch06$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch06$E$batch06$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch06$PT143-S3-Q9$batch06$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch06$Conclusion$batch06$, $batch06$There has never been life on the Moon.$batch06$), (1, $batch06$Evidence$batch06$, $batch06$If there had been life, there would be signs of it. Repeated trips have found no signs.$batch06$), (2, $batch06$Evaluate$batch06$, $batch06$If A, then B. No B. So no A. A required sign is missing, so the thing that would have left it never happened. Look for a firm conditional, a missing result, and a firm "no."$batch06$), (3, $batch06$Goal$batch06$, $batch06$If A then B; not B; so not A.$batch06$)) v(position,label,body) WHERE q.qid=$batch06$PT143-S3-Q9$batch06$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch06$A$batch06$, $batch06$No conditional at all, and the conclusion does not follow.$batch06$), ($batch06$B$batch06$, $batch06$Close in shape, but "almost empty" is not "no mayonnaise found," and the conclusion is only "unlikely." The original denies the sign outright and concludes firmly.$batch06$), ($batch06$C$batch06$, $batch06$It confuses a requirement with a guarantee and ends with a prediction. Not the same pattern.$batch06$), ($batch06$D$batch06$, $batch06$If A then B, B, so A. That affirms the result, which is the reverse of the original's move.$batch06$), ($batch06$E$batch06$, $batch06$If they plan an attack, there will be troop movements or weapons transfers. There are neither. So no attack is planned. Note the "either ... or" result: denying it means denying both, and the choice does.$batch06$)) v(letter,body) WHERE q.qid=$batch06$PT143-S3-Q9$batch06$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
